import{_ as s,o as t,c as i,a0 as e}from"./chunks/framework.DoRPXVp_.js";const k=JSON.parse('{"title":"Cross-network Cast（跨网络投屏）","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cast.md","filePath":"guide/cast.md"}'),n={name:"guide/cast.md"};function l(p,a,d,r,o,h){return t(),i("div",null,[...a[0]||(a[0]=[e(`<h1 id="cross-network-cast-跨网络投屏" tabindex="-1">Cross-network Cast（跨网络投屏） <a class="header-anchor" href="#cross-network-cast-跨网络投屏" aria-label="Permalink to &quot;Cross-network Cast（跨网络投屏）&quot;">​</a></h1><p>Cast 是构建在 Lattice overlay 网络之上的投屏能力：手机 / Mac 上的 Reflux 把视频&quot;投&quot;到加入同一 Lattice 网络的电视上，<strong>不限同一局域网</strong>——只要两端都在 Lattice 网络里（直连或经中继），投屏即可用。</p><h2 id="与传统投屏的区别" tabindex="-1">与传统投屏的区别 <a class="header-anchor" href="#与传统投屏的区别" aria-label="Permalink to &quot;与传统投屏的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>DLNA</th><th>Google Cast / AirPlay</th><th>Lattice Cast</th></tr></thead><tbody><tr><td>网络范围</td><td>同一局域网</td><td>同一局域网</td><td>任意 Lattice 网络（跨地域、跨 NAT）</td></tr><tr><td>发现机制</td><td>mDNS/SSDP 广播</td><td>生态内发现</td><td>控制面注册表（设备即节点）+ 局域网 mDNS</td></tr><tr><td>接收端门槛</td><td>电视预装</td><td>硬件或认证（Chromecast / MFi）</td><td>软件：装 App 即是（tvOS / Mac / Go renderer）</td></tr><tr><td>媒体传输</td><td>renderer 拉流，格式协商脆弱</td><td>sender 给 URL，receiver 拉流</td><td>同 URL 拉流 + overlay 直连，不通时自动走中继</td></tr><tr><td>安全</td><td>依赖局域网信任（裸奔）</td><td>生态内托管</td><td>WireGuard 加密 + renderer Bearer token</td></tr></tbody></table><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><p>一句话定位：<strong>Google Cast / AirPlay 做&quot;同一 WiFi 的客厅投屏&quot;，Lattice Cast 做&quot;私有内容 × 自有设备&quot;的跨网播放通道</strong>。</p><p>核心场景都是跨网的——这是上面三家协议结构上做不到的：</p><ul><li><strong>外网手机 → 家里电视</strong>：人在公司或出差，家里电视开着 Reflux，手机把 NAS / 115 网盘的影片投过去，家人在家直接看。命令走控制面（NATS），媒体走 overlay 直连（ICE 打洞，不通走 FERRY 中继）——内容与流量都不经过第三方。</li><li><strong>两处住宅互投</strong>：老家和城里的电视都在同一 Lattice 网络，任意一端的媒体库可被另一端投放。</li><li><strong>Mac/PC 作为接收端</strong>：卧室 Mac 装上 Reflux 即是富格式接收端（PlayerKit 渲染），手机把网盘剧集投给电脑看；LatticeMac 内置 AVPlayer 接收端在其离场时自动兜底。</li></ul><p>局域网内 Lattice Cast 与 AirPlay / DLNA 并存且可用（接收端是软件，无需任何硬件门槛），但<strong>同一 WiFi 下用户没有理由优先选它</strong>——遥控器上贴着的 AirPlay 标是现成的体验预期。这段能力是跨网通道顺路覆盖的一段，不是卖点。</p><h2 id="什么时候不用-cast" tabindex="-1">什么时候不用 cast <a class="header-anchor" href="#什么时候不用-cast" aria-label="Permalink to &quot;什么时候不用 cast&quot;">​</a></h2><ul><li><strong>内容在云端流媒体</strong>：电视 App 直接播更简单，还省一次拉流。cast 的价值在<strong>私有内容</strong>——NAS、网盘（115）、本地文件。</li><li><strong>接收端不归你管</strong>：酒店、朋友家的电视装不了你的 App，跨网 cast 无从落地。</li><li><strong>客厅多人同时投放</strong>：协议 v1 尚无 sender 会话仲裁（互踢/队列/音量同步是 Google Cast 打磨了十年的部分），多人场景会暴露。</li></ul><h2 id="架构总览" tabindex="-1">架构总览 <a class="header-anchor" href="#架构总览" aria-label="Permalink to &quot;架构总览&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> 发送端（iPhone / Mac）                控制面（latticed）              接收端（Apple TV）</span></span>
<span class="line"><span>┌─────────────────────┐          ┌────────────────────┐          ┌─────────────────────┐</span></span>
<span class="line"><span>│ Reflux App          │          │  NATS signaling    │          │ 隧道扩展进程（NE）     │</span></span>
<span class="line"><span>│  ├ 媒体服务 :47823 ◄┼──overlay─┤                    ├──NATS───►│  └ Lattice 引擎      │</span></span>
<span class="line"><span>│  │  (Range/206)     │  WireGuard│  设备注册表         │  cmd 订阅 │     ├ 收命令          │</span></span>
<span class="line"><span>│  └ 发布 cast 命令 ──┼───NATS──►│  投递 cast 命令     │          │     ├ overlay 拉流 ──┼──► AVPlayer</span></span>
<span class="line"><span>│                     │          │                    │◄──overlay─│     └ 状态上报        │</span></span>
<span class="line"><span>└─────────────────────┘          └────────────────────┘  status   └─────────────────────┘</span></span></code></pre></div><p>三条通道分工：</p><ol><li><strong>命令通道（NATS）</strong>：发送端把播放命令发到接收端的订阅主题，轻量、必达</li><li><strong>媒体通道（WireGuard overlay）</strong>：电视拿到媒体 URL 后直接向发送端拉流，大流量不经过控制面</li><li><strong>状态通道（overlay HTTP）</strong>：播放进度 / 状态周期性回传发送端</li></ol><h2 id="投屏生命周期" tabindex="-1">投屏生命周期 <a class="header-anchor" href="#投屏生命周期" aria-label="Permalink to &quot;投屏生命周期&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>配对（一次性）        电视打开 Reflux → 扫码加入 Lattice 网络 → 获得 overlay IP</span></span>
<span class="line"><span>                     引擎身份持久化，之后系统自动保活重连</span></span>
<span class="line"><span></span></span>
<span class="line"><span>投放                  发送端选择电视 → 起本地媒体服务 → 发布 play 命令（含媒体 URL）</span></span>
<span class="line"><span>                     电视引擎收到命令 → 回前台拉起播放器 → 向发送端拉流播放</span></span>
<span class="line"><span></span></span>
<span class="line"><span>播放中               每 5s 状态上报（进度 / 缓冲 / 错误）</span></span>
<span class="line"><span>                     发送端可随时投下一部（覆盖式）或停止</span></span>
<span class="line"><span></span></span>
<span class="line"><span>退出                  电视按返回键退出播放器；发送端 App 退出时媒体服务随生命周期关闭</span></span></code></pre></div><h2 id="命令通道细节" tabindex="-1">命令通道细节 <a class="header-anchor" href="#命令通道细节" aria-label="Permalink to &quot;命令通道细节&quot;">​</a></h2><p>每台接收端设备在控制面注册后有稳定身份（AppID），订阅主题为：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lattice.cast.&lt;appid&gt;.cmd</span></span></code></pre></div><p>命令是 JSON 载荷：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;id&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;uuid&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;action&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;play&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;url&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;http://&lt;发送端overlay-ip&gt;:47823/&lt;hash&gt;/&lt;file&gt;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;title&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;movie.mkv&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1717500000</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><ul><li>NATS 订阅在引擎内维护，断线重连后自动恢复订阅，<strong>离线期间的命令不补投</strong>（投屏是即时意图）</li><li>URL 的路径首段（<code>&lt;hash&gt;</code>）同时是状态回传的 Bearer 凭据——拿到 URL 即拿到本次投放会话的凭据，无需额外握手</li></ul><h2 id="媒体数据通道" tabindex="-1">媒体数据通道 <a class="header-anchor" href="#媒体数据通道" aria-label="Permalink to &quot;媒体数据通道&quot;">​</a></h2><p>发送端在投放时起一个本地媒体服务（监听 overlay IP 的 47823 端口），支持 HTTP Range 请求（206 Partial Content）。电视端 AVPlayer 以标准 Range GET 拉流，随机访问（seek）天然支持。</p><p>传输路径由 Lattice 的连接管理决定：优先 ICE 直连（P2P 打洞），失败时回落到 FERRY 中继。对播放器而言完全透明。</p><h2 id="状态回传" tabindex="-1">状态回传 <a class="header-anchor" href="#状态回传" aria-label="Permalink to &quot;状态回传&quot;">​</a></h2><p>电视端周期性 POST 到媒体 URL 同主机的 <code>/__cast/status</code>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST http://&lt;发送端overlay-ip&gt;:47823/__cast/status</span></span>
<span class="line"><span>Authorization: Bearer &lt;hash&gt;</span></span>
<span class="line"><span>{&quot;state&quot;: &quot;playing&quot;, &quot;position&quot;: 123.4, ...}</span></span></code></pre></div><p>发送端以此驱动投屏面板上的进度条与状态展示。接收端崩溃或断网时，发送端靠上报超时感知。</p><h2 id="tvos-上的引擎常驻设计" tabindex="-1">tvOS 上的引擎常驻设计 <a class="header-anchor" href="#tvos-上的引擎常驻设计" aria-label="Permalink to &quot;tvOS 上的引擎常驻设计&quot;">​</a></h2><p>传统做法引擎跑在 App 进程里——tvOS 会在 App 退后台后挂起进程，投屏就断了。Lattice 的 tvOS 方案把引擎下沉到 <code>NEPacketTunnelProvider</code> 扩展进程：</p><ul><li><strong>系统保活</strong>：隧道 profile 启用后，扩展进程由系统维持，App 退后台 / 被杀不影响接收投屏</li><li><strong>零流量捕获</strong>：隧道路由表为空（<code>includedRoutes = []</code>），不接管电视的任何普通流量，纯粹作为一个受系统保活的执行上下文</li><li><strong>App ⇄ 扩展 IPC</strong>：App 通过 <code>sendProviderMessage</code> 轮询引擎状态、下发打开媒体句柄等指令；投屏到达时 App 被拉起前台播放</li><li><strong>配置真源是 profile</strong>：引擎身份与服务器配置存于持久化的 VPN profile，系统重启后扩展重拉即自愈，无需 App 在场</li></ul><h2 id="调试工具-castcmd" tabindex="-1">调试工具：castcmd <a class="header-anchor" href="#调试工具-castcmd" aria-label="Permalink to &quot;调试工具：castcmd&quot;">​</a></h2><p>仓库自带命令行投播工具（<code>cmd/castcmd</code>），不依赖 App 即可验证整条链路：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">go</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./cmd/castcmd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -nats</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nats://</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">控制面地</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">址</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">:4222</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -appid</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">电视的AppI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">D</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -media</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://&lt;发送端overlay-ip&gt;:47823/&lt;hash&gt;/movie.mkv&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -title</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;测试影片&quot;</span></span></code></pre></div><table tabindex="0"><thead><tr><th>参数</th><th>说明</th></tr></thead><tbody><tr><td><code>-nats</code></td><td>控制面 NATS 地址（命令走此通道）</td></tr><tr><td><code>-appid</code> / <code>-peerid</code> / <code>-pubkey</code></td><td>目标设备三种定位方式，优先级依次递减</td></tr><tr><td><code>-media</code></td><td>媒体 URL（必需）</td></tr><tr><td><code>-transport</code></td><td><code>nats</code>（默认）或 <code>overlay</code>（直发 UDP 数据报到引擎命令口 47822，等 ACK）</td></tr></tbody></table><p><code>-transport overlay</code> 用于验证 ICE 直连数据面是否健康，与 NATS 通道互为对照。</p><h2 id="故障排查速查" tabindex="-1">故障排查速查 <a class="header-anchor" href="#故障排查速查" aria-label="Permalink to &quot;故障排查速查&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>检查</th></tr></thead><tbody><tr><td>发送端找不到电视</td><td>电视是否在线（控制面设备列表）；两端是否同一网络</td></tr><tr><td>命令已发但电视无反应</td><td>用 castcmd 复现；确认电视引擎的 NATS 连接在（控制面侧）；电视 App 是否完成配对（VPN profile 已允许）</td></tr><tr><td>命令到了但不播</td><td>媒体 URL 是否可达（电视 → 发送端 overlay 连通性）；发送端媒体服务是否还在</td></tr><tr><td>能播但频繁卡顿</td><td>大概率走了中继（ICE 直连未建成），检查两端 NAT 类型；见 <a href="/design/ice-connection">ICE Connection</a></td></tr><tr><td>电视重启后失联</td><td>引擎应自动重连重注册；检查 VPN profile 是否仍启用（设置 → VPN）</td></tr></tbody></table>`,40)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
